-- Operating rhythm cell (operating), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA operating;

CREATE FUNCTION operating.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE operating.cycles (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    cycle_type               text NOT NULL DEFAULT 'sprint' CHECK (cycle_type IN ('sprint', 'weekly', 'planning', 'review')),
    status                   text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'active', 'in_review', 'closed', 'cancelled')),
    start_date               date NOT NULL,
    end_date                 date NOT NULL,
    focus                    text NOT NULL CHECK (length(focus) >= 1),
    capacity_minutes         integer CHECK (capacity_minutes IS NULL OR (capacity_minutes >= 0)),
    owner                    text NOT NULL DEFAULT 'Owner' CHECK (length(owner) <= 200),
    decision                 text CHECK (decision IS NULL OR (decision IN ('continue', 'adjust', 'pause', 'close'))),
    source                   text NOT NULL DEFAULT 'ai-operating-cadence' CHECK (length(source) <= 200),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug)
);
CREATE UNIQUE INDEX cycles_legacy ON operating.cycles (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX cycles_cycle_type ON operating.cycles (workspace_id, cycle_type);
CREATE INDEX cycles_slug ON operating.cycles (workspace_id, slug);
CREATE INDEX cycles_status ON operating.cycles (workspace_id, status);

CREATE TABLE operating.kpis (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    description              text NOT NULL CHECK (length(description) >= 1),
    unit                     text NOT NULL DEFAULT 'count' CHECK (length(unit) <= 60),
    direction                text NOT NULL DEFAULT 'increase' CHECK (direction IN ('increase', 'decrease', 'maintain')),
    target_value             double precision NOT NULL,
    source_kind              text NOT NULL CHECK (source_kind IN ('cycle_tasks', 'ai_telemetry', 'review', 'manual')),
    privacy_class            text NOT NULL DEFAULT 'internal' CHECK (privacy_class IN ('public', 'internal', 'private')),
    metric_group             text NOT NULL DEFAULT 'operating' CHECK (length(metric_group) <= 100),
    measurement_cadence      text NOT NULL DEFAULT 'weekly' CHECK (length(measurement_cadence) <= 60),
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'retired')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug)
);
CREATE UNIQUE INDEX kpis_legacy ON operating.kpis (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX kpis_metric_group ON operating.kpis (workspace_id, metric_group);
CREATE INDEX kpis_slug ON operating.kpis (workspace_id, slug);
CREATE INDEX kpis_source_kind ON operating.kpis (workspace_id, source_kind);
CREATE INDEX kpis_status ON operating.kpis (workspace_id, status);

CREATE TABLE operating.cycle_tasks (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    cycle_id                 bigint NOT NULL,
    task_id                  bigint NOT NULL,
    commitment_type          text NOT NULL DEFAULT 'committed' CHECK (commitment_type IN ('committed', 'stretch', 'carried_over', 'dropped')),
    estimate_minutes         integer CHECK (estimate_minutes IS NULL OR (estimate_minutes >= 0)),
    evidence_required        boolean NOT NULL DEFAULT true,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, cycle_id, task_id),
    FOREIGN KEY (workspace_id, cycle_id) REFERENCES operating.cycles (workspace_id, id)
);
CREATE UNIQUE INDEX cycle_tasks_legacy ON operating.cycle_tasks (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX cycle_tasks_commitment_type ON operating.cycle_tasks (workspace_id, commitment_type);
CREATE INDEX cycle_tasks_cycle_id ON operating.cycle_tasks (workspace_id, cycle_id);
CREATE INDEX cycle_tasks_task_id ON operating.cycle_tasks (workspace_id, task_id);

CREATE TABLE operating.cycle_goal_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    cycle_id                 bigint NOT NULL,
    goal_id                  bigint NOT NULL,
    link_type                text NOT NULL DEFAULT 'objective' CHECK (link_type IN ('objective', 'supporting', 'guardrail')),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, cycle_id, goal_id),
    FOREIGN KEY (workspace_id, cycle_id) REFERENCES operating.cycles (workspace_id, id)
);
CREATE UNIQUE INDEX cycle_goal_links_legacy ON operating.cycle_goal_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX cycle_goal_links_cycle_id ON operating.cycle_goal_links (workspace_id, cycle_id);
CREATE INDEX cycle_goal_links_goal_id ON operating.cycle_goal_links (workspace_id, goal_id);
CREATE INDEX cycle_goal_links_link_type ON operating.cycle_goal_links (workspace_id, link_type);

CREATE TABLE operating.cycle_reviews (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    cycle_id                 bigint NOT NULL,
    reviewer                 text NOT NULL DEFAULT 'Owner' CHECK (length(reviewer) <= 200),
    summary                  text NOT NULL CHECK (length(summary) >= 1),
    delivered_summary        text,
    carryover_summary        text,
    blocker_summary          text,
    learning_summary         text,
    decision                 text NOT NULL CHECK (decision IN ('continue', 'adjust', 'pause', 'close')),
    evidence_ref             text,
    reviewed_at              timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, cycle_id),
    FOREIGN KEY (workspace_id, cycle_id) REFERENCES operating.cycles (workspace_id, id)
);
CREATE UNIQUE INDEX cycle_reviews_legacy ON operating.cycle_reviews (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX cycle_reviews_cycle_id ON operating.cycle_reviews (workspace_id, cycle_id);
CREATE INDEX cycle_reviews_decision ON operating.cycle_reviews (workspace_id, decision);

CREATE TABLE operating.kpi_measurements (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    kpi_id                   bigint NOT NULL,
    cycle_id                 bigint NOT NULL,
    value                    double precision NOT NULL,
    target_value             double precision NOT NULL,
    status                   text NOT NULL DEFAULT 'no_data' CHECK (status IN ('no_data', 'on_track', 'at_risk', 'off_track', 'achieved')),
    measured_at              timestamptz,
    source_ref               text,
    evidence_ref             text,
    metadata_json            text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, kpi_id, cycle_id),
    FOREIGN KEY (workspace_id, kpi_id) REFERENCES operating.kpis (workspace_id, id),
    FOREIGN KEY (workspace_id, cycle_id) REFERENCES operating.cycles (workspace_id, id)
);
CREATE UNIQUE INDEX kpi_measurements_legacy ON operating.kpi_measurements (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX kpi_measurements_cycle_id ON operating.kpi_measurements (workspace_id, cycle_id);
CREATE INDEX kpi_measurements_kpi_id ON operating.kpi_measurements (workspace_id, kpi_id);
CREATE INDEX kpi_measurements_status ON operating.kpi_measurements (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE operating.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('cycle', 'cycle-task', 'cycle-goal-link', 'cycle-review', 'kpi', 'kpi-measurement')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE operating.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON operating.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['cycles', 'kpis', 'cycle_tasks', 'cycle_goal_links', 'cycle_reviews', 'kpi_measurements', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE operating.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE operating.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON operating.%I'
                       ' USING (workspace_id = operating.current_workspace())'
                       ' WITH CHECK (workspace_id = operating.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA operating TO operating_api;
GRANT EXECUTE ON FUNCTION operating.current_workspace() TO operating_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON operating.cycles, operating.kpis, operating.cycle_tasks, operating.cycle_goal_links, operating.cycle_reviews, operating.kpi_measurements TO operating_api;
GRANT USAGE ON SEQUENCE operating.cycles_id_seq, operating.kpis_id_seq, operating.cycle_tasks_id_seq, operating.cycle_goal_links_id_seq, operating.cycle_reviews_id_seq, operating.kpi_measurements_id_seq TO operating_api;
GRANT SELECT, INSERT ON operating.create_keys TO operating_api;
GRANT SELECT, INSERT ON operating.outbox TO operating_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON operating.outbox TO operating_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON operating.outbox TO operating_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA operating TO operating_publisher;
GRANT SELECT ON operating.outbox TO operating_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON operating.outbox TO operating_publisher;
